quests[52943] = { id = 52943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling Out the Clans", description = "This Overlord Geya'rah has a fire inside her. I may come to like her... if she doesn't kill us.\n\nWe have but one chance. You pay homage to the symbol of each clan, and I will speak of it.\n\nShow respect--or they will show us the executioner's blade.", progress = "I do not have time for this.", completion = "So, you know of our clans.", objectives = "Pay homage to the orc clan symbols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52944] = { id = 52944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Drustvar", description = "We've discovered a spike of Horde activity within Drustvar. We cannot allow them to get the upper hand.", completion = "Great work, {class}.", objectives = "Slay Horde within Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52945] = { id = 52945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonds Forged Through Battle", description = "Geya'rah has a fiery spirit... like her mother. Perhaps facing a common foe will ease her wariness.\n\nWe subdued the ogre clans long ago. But every so often, one of their bravest--and stupidest--stirs the embers of rebellion. Today is such a day.\n\nYou and Eitrigg will join Geya'rah in putting down the ogre uprising. Prove yourself in battle and you may earn her respect.", progress = "Don't slow me down.", completion = "We have to deal with an ogre uprising every few seasons.", objectives = "Assist Geya'rah in putting down the ogre uprising.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52946] = { id = 52946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dying World", description = "Champion, Azeroth be dyin' while the armies of the Horde and Alliance be fightin' over a ruined city.\n\nShe needs yer help. Make yer way to me camp in Silithus. Azeroth's got somethin' tae give ye.", completion = "Ye made it. We don't have any time tae lose.", objectives = "Meet Magni Bronzebeard in Silithus, located within Kalimdor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52947] = { id = 52947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ettin Outta Here" }
