quests[52949] = { id = 52949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Nazmir", description = "It's time to press the attack within Horde territory, {class}! Travel to Nazmir and slay as many Horde as you find.", completion = "Great work, {class}.", objectives = "Slay Horde within Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
