quests[52952] = { id = 52952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Zuldazar", description = "We're getting reports of increased Alliance activity within Zuldazar. Head over there and clear them out.", completion = "Good work, {class}.", objectives = "Slay Alliance within Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
