quests[52954] = { id = 52954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Nazmir", description = "We're getting reports of increased Alliance activity within Nazmir. Head over there and clear them out.", completion = "Good work, {class}.", objectives = "Slay Alliance within Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52955] = { id = 52955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyranny of the Light", description = "If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound.\n\nShould the reports prove true, this is the closest they have dared approach our stronghold in quite some time.\n\nCome or stay, but make your decision quickly.", completion = "To think of those we just lost... it is... No, it is of no use.", objectives = "Assist Geya'rah against the Tyranny of the Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52956] = { id = 52956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Tiragarde Sound", description = "Its time to hit the Alliance at the source. Travel to Tiragarde Sound and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", completion = "Good work, {class}.", objectives = "Slay Alliance within Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52957] = { id = 52957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Stormsong Valley", description = "Its time to hit the Alliance at the source. Travel to Stormsong Valley and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", completion = "Good work, {class}.", objectives = "Slay Alliance within Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52958] = { id = 52958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Drustvar", description = "Its time to hit the Alliance at the source. Travel to Drustvar and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", completion = "Good work, {class}.", objectives = "Slay Alliance within Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52962] = { id = 52962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Mistvine Ledge", description = "Your followers have sent a report regarding the assault on Mistvine Ledge.\n\nIt details that victory was hard-fought, but the enemies surrounding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52963] = { id = 52963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistvine Ledge", description = "The raid you planned for Mistvine Ledge in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mistvine Ledge in Zuldazar and establish fortifications there.\n\nMistvine Ledge will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", completion = "Greetings, {name}. Mistvine Ledge will surely be one of our most valuable outposts. We have a direct view of the Golden Throne and the jungle canopy provides ample camoflauge.", objectives = "Claim Mistvine Ledge for the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52964] = { id = 52964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Problem" }
quests[52965] = { id = 52965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52967] = { id = 52967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurfang Returns", description = "Saurfang! It's about time.\n\nLook around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. \n\nNow is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.", completion = "Our journey was treacherous, but we never lost sight of our goal.", objectives = "Find Saurfang in Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52968] = { id = 52968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for a Little Blood" }
quests[52970] = { id = 52970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Small Mercy", description = "I will not slay innocents. If they do not raise arms against us, we shall spare them.\n\nEnter Lor'danel and capture any civilians you find there. They shall be questioned and then released.", completion = "We've shown honor to our enemy today.", objectives = "Capture 8 Lor'danel citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52971] = { id = 52971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Rendezvous", description = "Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back.\n\nOne swift strike and we can end this threat!\n\nYou will break through their lines and slay the two commanders. Without leadership this force will crumble.", completion = "I congratulate you on your success, but I sense something is not right...", objectives = "Kill Caranne Briarbow and Ariel Stagguard", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52972] = { id = 52972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored Grandchild" }
quests[52973] = { id = 52973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Threat from the North", description = "The Horde must have scaled the mountains of Felwood in the North. \n\nThe wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. \n\nWe must weather this attack together.", completion = "No matter the odds, we must stay strong.", objectives = "Find Malfurion Stormrage in Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52974] = { id = 52974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Effort", description = "The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. \n\nLocate these civilians and send them to safety. We're counting on you, {name}.", completion = "You've saved many lives today, {name}. You have my thanks.", objectives = "Rescue 8 Lor'danel citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52975] = { id = 52975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Action This Day", description = "Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, {name}.\n\nIf they take our ships, they will use them to sail to Darnassus!\n\nSlay the two warriors leading the attack, and the rest of them will give up the fight.", completion = "Have you heard from Malfurion recently?", objectives = "Eliminate Gormok Axefall, and Ragash Bloodwish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52977] = { id = 52977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guidance of Our Shan'do", description = "Lor'danel is overrun. The Horde... they -- they just don't relent.\n\nThere is nothing we can do, {name}. We must find our Shan'do and ask for his guidance. \n\nHe is the only one who can save us.", completion = "{name}! The tree...", objectives = "Find Malfurion Stormrage in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52978] = { id = 52978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Prince in Tow", description = "Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.", completion = "Once again, excellent work, {name}.", objectives = "Speak with Dread-Admiral Tattersail to return to Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52979] = { id = 52979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Cleansing" }
quests[52981] = { id = 52981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killer Queen", description = "Lor'danel is now secure, but something is amiss... there has been no sign of Stormrage. \n\nMalfurion would have never let Lor'danel fall without a fight. He must have gone after her.\n\nMy army has approached from the North, and our reinforcements have arrived from the South -- which means that they are not along any of the roads.\n\nSearch the forest with me, {name}. We will find them and be done with this once and for all.", progress = "The Horde endures.", completion = "<The flames cast Sylvanas' face in shadow.>", objectives = "Scour the forest of Darkshore to find the Warchief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52982] = { id = 52982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mine or Trouble" }
quests[52983] = { id = 52983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Want It All", description = "An elemental born of pure Azerite! I do not know what kind of threat this poses, champion... but please, do take care.", objectives = "Defeat the Azerite Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52984] = { id = 52984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Want It All", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52986] = { id = 52986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wicked Vessel" }
quests[52987] = { id = 52987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Burn!" }
quests[52988] = { id = 52988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House Cleaning" }
quests[52990] = { id = 52990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Harbor", description = "With the scepter in hand, let us return to the portal.\n\nI believe Stone would agree with me when I say that it is best for us to get away from Kul Tiras for a while.", completion = "it seems your mission was a success. Good.", objectives = "Return to Nathanos Blightcaller in Plunder Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53003] = { id = 53003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cycle of Hatred", description = "We have raised new champions for the Horde, established footholds on Kul Tiran soil, and stolen one of their precious artifacts.\n\nWe hold greater power and sway over our enemies than we have before.\n\nSylvanas has great plans for our Horde, {name}. I will allow you the pleasure of reporting our victories to her personally.", completion = "{name}. Nathanos has been updating me on your progress throughout your efforts.\n\nThe Alliance, and the Kul Tirans, shall tremble before the might of my Horde.", objectives = "Report to Sylvanas Windrunner in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53006] = { id = 53006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Grimwatt's Crash", description = "Your followers have sent a report regarding the rescue mission to Grimwatt's Crash.\n\nIt details that the supplies were recovered and the enemies surrounding the crash site have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Nazmir?", completion = "It seems the mission to Grimwatt's Crash was a success. Well done, {name}.\n\nI think it will make a fine outpost. I'll send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53007] = { id = 53007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimwatt's Crash", description = "The rescue that you planned for Grimwatt's Crash in Nazmir was successful. Well done.\n\nI believe we should fortify the crash site and turn it into an outpost.\n\nMake your way to Grimwatt's Crash and establish fortifications there.\n\nGrimwatt's Crash will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", completion = "The crash site was surrounded when we arrived. It's a good thing we made it in time.", objectives = "Claim Grimwatt's Crash for the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53008] = { id = 53008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage Wisdom" }
quests[53009] = { id = 53009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hang On In There", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53010] = { id = 53010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Turning Back", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53011] = { id = 53011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53012] = { id = 53012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Away Your Toys" }
quests[53025] = { id = 53025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culling" }
quests[53027] = { id = 53027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edge of Glory" }
quests[53028] = { id = 53028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dying World", description = "Champion. Magni Bronzebeard needs your help.\n\nAzeroth is dying. Before this war, a massive demon called Sargeras stabbed the planet with a sword.\n\nOur planet cries out in pain while the Horde and Alliance fight amongst each other.\n\nMagni Bronzebeard believes you can help heal the planet's wounds.\n\nMeet him in Silithus. He has set up camp where Sargeras's sword impacted our world.", completion = "Ye made it. We don't have any time tae lose.", objectives = "Meet Magni Bronzebeard in Silithus, located within Kalimdor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53029] = { id = 53029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dying World", description = "While the armies of the Horde and Alliance squabble over a ruined city, our world is dying, {name}.\n\nMagni Bronzebeard, the Speaker of Azeroth, needs you at his encampment in Silithus.\n\nYou must hurry. The area is being overrun by elementals driven mad by Azerite!", completion = "Ye made it! Good. We don't have any time tae lose.", objectives = "Meet Magni Bronzebeard in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53030] = { id = 53030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture across these lands, and give aid where you may, to prove your worth.", progress = "I foresee that you will win many friends this week.", completion = "Well done, {name}.", objectives = "Complete 20 World Quests in Kul Tiras, Zandalar, Arathi Highlands, Darkshore, or Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53031] = { id = 53031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Imperative", description = "The world's soul is secure... fer now. I can hear Azeroth again, though her voice is still weak.\n\nThe elementals on the surface above have calmed down. Even using just a fraction of its power, the Heart of Azeroth brought stability tae this place.\n\nYe need tae return tae Orgrimmar and inform yer allies what transpired here. Remind them that no matter what happens in their war, our world must be saved.\n\nWe'll speak again soon, {name}. The battle fer Azeroth has only just begun.", completion = "It would seem you were in the right place at the right time, {name}. This Heart of Azeroth the dwarf gave you may prove useful indeed.\n\nBut the war must remain our sole focus. We can spare no forces to aid Magni on his grand crusade.\n\nThe Alliance will stop at nothing to destroy the Horde. Fortunately, the Dark Lady has a plan to make us stronger.", objectives = "Speak with Nathanos Blightcaller in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53032] = { id = 53032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53033] = { id = 53033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53034] = { id = 53034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the Destroyer's star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53035] = { id = 53035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53036] = { id = 53036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", completion = "I trust your battles went well. And that's not just a turn of phrase. I know they did. I knew they would.", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53037] = { id = 53037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "When the sign of the warrior shines in the night sky, fortune favors the daring. Powerful foes may yield even greater rewards. Venture deep into caverns and strongholds to prove your worth.", progress = "I foresee significant amounts of loot in your future.", completion = "Well done, {name}. I knew you could do it.", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53038] = { id = 53038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", progress = "I foresee that you will travel across the land, searching far and wide. It's your destiny.", completion = "Well done, {name}. With courage, you have faced every challenge along the way, and battled every day to claim your rightful place.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53039] = { id = 53039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", progress = "I foresee blood in your future, {name}.", completion = "Well done, {name}. I knew you would do it.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53040] = { id = 53040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squall Squelching" }
quests[53041] = { id = 53041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sampling the Goods", description = "Bridgeport is a major trade hub for this area. Naturally, Ashvane has offices and workshops here.\n\nCheck around town and see if you can learn anything about this new material and how they're using it.\n\nIf you can lift a sample for us to send back to Boralus, even better.\n\nI gotta stay here and keep an eye on someone.", progress = "<Flynn side-eyes you while trying his best to look casual.>\n\nYou get what we need?", completion = "Good, I'll hang onto them for now.\n\nI think I've found our next lead.", objectives = "Collect the Chemist's Notes and a Raw Azerite Sample.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53042] = { id = 53042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller" }
quests[53043] = { id = 53043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Vulture's Nest", description = "Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun.\n\nIt details that the mission was a success and that the troops holding the outpost have requested reinforcements.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Vol'dun?", completion = "It seems the mission to Vulture's Nest was a success. Well done, {name}.\n\nI'll send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53044] = { id = 53044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulture's Nest", description = "The mission to take Vulture's Nest in Vol'dun was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Vulture's Nest and establish fortifications there.\n\nIt will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", completion = "This outpost gives us an ideal vantage point for monitorin' the movements o' the sethrak forces below.", objectives = "Claim Vulture's Nest for the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53045] = { id = 53045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Wharf", description = "Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. \n\nIt was also in the direct war path of the naga -- who knows what remains now.\n\nIf you could stop in and check in on its leader, Coxswain Hook, you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.", completion = "Ah, just what I needed. A fresh set o' ears to hear a tale or two!", objectives = "Speak to Coxswain Hook in Thresher's Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53050] = { id = 53050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper Into Kul Tiras", description = "It is time for us to further our hold on Kul Tiras.\n\nReturn to the Banshee's Wail. From there we shall plan our next course of action.", completion = "It is time to establish another foothold, {name}. Are you prepared?", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53052] = { id = 53052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper Into Zandalar", description = "Our advisors have decided that now is the correct time to further our hold on Zandalar.\n\nReturn to the Wind's Redemption posthaste. We shall leave for new lands immediately.", completion = "Welcome back, {name}. Let's get to work.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53053] = { id = 53053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Mugambala!", description = "The Rastari have proven to be formidable allies in combat, and reports are coming in that help explain how they've honed their battle prowess. \n\nJe'stry the Untamed has a fighting ring setup at the base of Mount Mugambala that could prove useful for getting ready for war.  We've dispatched our troops to take advantage of these training grounds, go and see what High Warlord Volrath has uncovered.", completion = "Welcome to the Dueler's Guild, {name}.", objectives = "Speak with High Warlord Volrath at The Mugambala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53054] = { id = 53054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would find benefit in this Dueler's Guild.  Speak with a nearby Rastari Guard to participate in the carnage.", completion = "Good luck in The Mugambala, {race}.", objectives = "Speak with a nearby Rastari Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53055] = { id = 53055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Our Influence", description = "Our scouts have identified a location for a final major foothold in Zandalar.\n\nReturn to the Wind's Redemption so we can ship out.", completion = "It is time to establish our final major foothold in Zandalar, {name}.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53056] = { id = 53056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Our Influence", description = "We have identified a location for a final major foothold in Kul Tiras.\n\nReturn to the Banshee's Wail to discuss our new mission.", completion = "It is time to establish our final major foothold in Kul Tiras.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53061] = { id = 53061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azerite Advantage", description = "{name}, we have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must acquire this precious resource before our enemies in the Horde.\n\nReport to the Wind's Redemption as soon as possible to aid in extraction.", completion = "We appreciate your timeliness, {name}. We must move quickly.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53062] = { id = 53062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azerite Advantage", description = "We have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must move quickly to acquire these resources for the Horde.\n\nReport to the Banshee's Wail to aid in this urgent mission.", completion = "We cannot waste any time.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53063] = { id = 53063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission of Unity", description = "You have done much for the Alliance during your time here in Kul Tiras, {name}.\n\nToday we must ask more of you. Return to the Wind's Redemption when you have the chance so that we can discuss.", progress = "The Alliance needs us to bring our new allies into the fold.", completion = "I have another important mission for you, {name}.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53064] = { id = 53064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission of Unity", description = "You have undertaken great journeys during your time here in Zandalar.\n\nIt is time for your next mission. Report to the Banshee's Wail.", progress = "We must bring the Zandalari into the Horde.", completion = "Are you prepared for your next mission?", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53065] = { id = 53065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Grave Digger", description = "Sylvanas has issued us a mission in Drustvar, where we will find our next target.\n\nReport to the Banshee's Wail immediately.", completion = "Good. You didn't dawdle.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53066] = { id = 53066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Water Wise", description = "Rexxar has reported back with news of a new... ally.\n\nReport to the Banshee's Wail for your briefing.", completion = "Get ready to set sail for Stormsong Valley.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53067] = { id = 53067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Bottom Feeder", description = "It is time for Zelling to prove his worth to the Horde.\n\nReturn to the Banshee's Wail. Today, we sail out to open waters.", completion = "Interested in some deep sea diving?", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53068] = { id = 53068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Hook and Line", description = "Thanks to the help of our new allies, we have devised a plan to extract a powerful tidesage artifact from Boralus.\n\nI have already sent Valentine to get us started.\n\nReport to the Banshee's Wail posthaste.", completion = "I hope you are prepared for some light infiltration, {name}.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53069] = { id = 53069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Blood Arrow", description = "We have uncovered the location of a high priority target in Nazmir.\n\nReturn to the Wind's Redemption for your briefing.", completion = "We return to the harsh lands of Nazmir today, {name}. I hope you are prepared.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53070] = { id = 53070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Cutpurse", description = "It is time to reconvene for our next mission, though Shandris and I disagree on what exactly that should entail.\n\nMeet us on the Wind's Redemption.", completion = "I feel we are close to a conclusion, {name}. Perhaps your presence here will help.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53071] = { id = 53071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gryphon's Claw", description = "SI:7 has procured some interesting intel.\n\nI request your presence on the Wind's Redemption immediately to help decide our next course of action.", completion = "Thank you for arriving with such haste.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53072] = { id = 53072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Heartstrike", description = "We've taken out quite a number of high priority targets, {name}. All thanks to your help.\n\nIt is time to strike directly at the heart of the Zandalari empire.\n\nReport to the Wind's Redemption as soon as you are able. We will get started from there.", completion = "We're going to need to pull out all the stops on this one.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53073] = { id = 53073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook Point Investigation", description = "I'm sure you've heard the constant sound of battle coming from Hook Point.\n\nWe sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground.\n\nDaniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.", completion = "So you've found the Dueler's Guild, {name}.", objectives = "Speak with Grand Marshal Tremblade at Hook Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53074] = { id = 53074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", progress = "Have you issued the recruitment order?", completion = "Excellent. Your new recruits will be available for missions once they have finished their training.", objectives = "Speak with Mathias Shaw to issue a recruitment order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53075] = { id = 53075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would benefit from training in the Dueler's Guild.  Speak with a nearby bouncer to participate in the carnage.", completion = "Good luck in the Dueler's Guild, {race}.", objectives = "Speak with a nearby bouncer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53076] = { id = 53076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foundry Meltdown" }
quests[53078] = { id = 53078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure in the Tides", objectives = "Loot 8 Shipwreck Supplies in the Wailing Tideway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53079] = { id = 53079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", progress = "Have you issued the recruitment order?", completion = "Good. Your new recruits will be available for missions once they have finished their training.", objectives = "Speak with Garona Halforcen to issue a recruitment order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53081] = { id = 53081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Spare Parts", description = "Your followers have sent a report regarding the mission to collect salvage for Stonefist Watch.\n\nIt details that the mission was a success and the necessary materials have been collected.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission for Stonefist Watch?", completion = "It seems the mission to gather supplies for Stonefist Watch was a success. Well done, {name}.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53082] = { id = 53082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts", description = "An engineer has been assigned to Stonefist Watch to build a scrapping machine.\n\nThe mission to salvage materials for the machine was a success thanks to your leadership.\n\nMake your way to Stonefist Watch in Tiragarde Sound and meet with Grizvek Gearsnap. He has been overseeing the upgrades for the outpost.", completion = "This machine here will break anything apart! Go ahead, try it out!", objectives = "Speak with Grizvek Gearsnap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53095] = { id = 53095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flicker of Hope", description = "Champion, I need your help!\n\nWe must evacuate Darnassus before it burns to ash! Many of the city's structures have already caught fire. Douse the flames and rescue the trapped civilians within!\n\nPlease, do all that you can... we must save as many lives as possible.", objectives = "Evacuate the Citizens of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53096] = { id = 53096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[53097] = { id = 53097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Despondent Ablutions", description = "You return. A surprise. Perhaps there is still hope.\n\nIn victory or defeat, you bear the weight of this place. It hangs on you like a mantle. I see your struggle to bear it.\n\nThere is, perhaps, a way to shrug off this burden. An altar, to the northwest. Built by the tidesages, seeking to wash away the corruption.\n\nOffer yourself to the idol. It will exact a price, as do all things. But in communion you may claw back from the brink.", progress = "Find the circle, pierce the veil. Only in oblivion can you find it.", completion = "Your mind has rejected madness, and replaced it with determination. For now.", objectives = "Investigate the Purifying Effigy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53098] = { id = 53098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Shandris Feathermoon", objectives = "Champion, it has been an honor to fight by your side. Our battle against the Horde is far from over.\n\nShould you ever need my aid, simply call and I shall be there. Only by working together will we stop Sylvanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53099] = { id = 53099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mote of Cosmic Truth", description = "We stand on the brink, you and I. The final act looms over us, casting a terrible shadow.\n\nDeep we plumbed, seeking knowledge of the world. Deeper still we delved, until our fate was inevitable. Minds were shattered, my comrades ran screaming into the night. We are all lost, to that terrible Thing...\n\nNow, the malformed syzygy beckons. Complete the ritual and bring about the end.", completion = "Victory... foolish and meaningless.", objectives = "Defeat the Ascendant Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53100] = { id = 53100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Giant Slaying", description = "Your followers have sent a report regarding the mission at Stonetusk Watch.\n\nIt details that the mission was a success and that one of the ettins is being held captive.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission for Stonetusk Watch?", completion = "It seems the mission at Stonetusk Watch was a success. Well done, {name}.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53101] = { id = 53101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nettin' Ettin", description = "An ettin has been captured by our troops at Stonetusk Watch.\n\nApparently, the creature is being trained to work for the Horde as a beast of burden.\n\nMake your way to Stonetusk Watch in Stormsong Valley and meet with Wyna Breezehorn. She has been training the ettin to do her bidding.", completion = "Ettins aren't as hard to train as you might think. Go ahead and take Donk for a ride. It's okay, he's friendly enough!", objectives = "Speak with Wyna Breezehorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53102] = { id = 53102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Nature Calls", description = "Your followers have sent a report regarding the mission at Swiftwind Post.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission for Swiftwind Post?", completion = "It seems the mission at Swiftwind Post was a success. Well done, {name}.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53103] = { id = 53103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicker Magic", description = "It seems that the druids at Swiftwind Post have learned much from the ancient Drust rituals you recovered.\n\nThe druids are now able to offer improved services at the outpost.\n\nMake your way to Swiftwind Post in Drustvar and see what they have to offer.", completion = "We've learned much from the Drust's unique form of nature magic. We now have some special boons to offer you, {name}.\n\nThese blessings of nature are yours whenever you visit.", objectives = "Speak with Toska Eaglehorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53105] = { id = 53105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misplaced Faith", description = "The air is foul with corruption. It must be dealt with.\n\nThe tidesages were fools, and I a fool to trust them. Belief in their god to perform miracles and deliver us from our folly. Nevertheless, their methods did serve to drive back the foul presence from these cliffs.\n\nA simple censer, loaded with select powders and oils. The vapors produce an effect that expels the miasma, if only for a time.\n\nPerhaps their ineffectual gesticulation will finally serve a purpose.", completion = "The foul odor is dispersed. Perhaps reality can once more take root in this place.", objectives = "Use the Cleansing Thurible to purge 13 sources of corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53106] = { id = 53106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Censership" }
quests[53107] = { id = 53107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder and Provisions" }
quests[53108] = { id = 53108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iconoclasm" }
quests[53109] = { id = 53109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House Waycrest", description = "You have done much for my home and the people of Drustvar,\n\nTell your allies that House Waycrest will return to Boralus shortly.", completion = "I cannot believe all that has gone on in Drustvar!\n\nI am thankful that House Waycrest will return.", objectives = "Return to Taelia in the Harbormaster's Office in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53110] = { id = 53110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Thornspeaker", description = "My teacher, Ulfar, the High Thornspeaker, must be informed of what's been going on here.\n\nI can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs.\n\nYou have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. \n\nArthur will meet you at the head of the path to Ulfar's den.", progress = "What do you have there, mainlander?", completion = "What do you have here, mainlander? Ah, I see. My students met with much stronger threats than we'd expected.\n\nThank you for helping them.", objectives = "Take the Runic Power Cores to Ulfar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53112] = { id = 53112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth's Tear", progress = "What do ye have there?", completion = "By the forge! What ye got there is... truly somethin'. A shard of concentrated agony... our world's torment given form. It hurts me tae even look at it.\n\nYet within all that sadness, there is power, too. We can use its energy to help heal the wound. Maybe even bring Azeroth some solace.\n\nThank ye for bringin' it to me, {name}." }
quests[53113] = { id = 53113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmering Shell", progress = "Hello! Can I help you?", completion = "What's that? Oh! It's so pretty! I've never seen a shell like this before!\n\nI could make so many different things from it. Oh, think of the jewelry!\n\nThis is so great, thanks!\n\n<Jena hesitates a moment, then gives you a quick lick on the cheek.>" }
quests[53114] = { id = 53114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golden Beetle", progress = "<Krag'wa's bulbous eyes turn towards you.>", completion = "<Krag'wa's eyes widen as you pull out the beetle. Before you can react, his enormous, sticky tongue whips out and snatches it from your hand. In a moment he has gulped down the prize.>\n\n<Krag'wa settles down onto his belly, emits a satisfied belch, and closes his eyes.>" }
quests[53115] = { id = 53115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island Flotsam", progress = "'Eh richmon. Whatchya be bringin' me?", completion = "<Jani sniffs the air, smelling your wet garbage.>\n\nYa brought ol' Jani a present! What ya got there? Let me see it.\n\n<Jani begins rooting through the pile of trash you have brought.>\n\nOh, yes, and some of this, mmm, mmmhm, yes, oh that's sticky...\n\n<Jani seems pleased with your offering, and is paying no attention to you any longer.>" }
quests[53116] = { id = 53116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rusted Horde Insignia", progress = "Lok'tar, hero.", completion = "Ah, yes, I see.\n\nThis war will not come without loss, hero. This insignia belonged to a member of the Horde who fell in battle. \n\nIt is the way of war, and yet I cannot help but think of the families of these soldiers. \n\nI will do what I can for them, thank you for bringing this to me." }
quests[53117] = { id = 53117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rusted Alliance Insignia", progress = "Yes, champion?", completion = "This war will not be without casualties, it is a shame that so much must be lost to keep what we hold dear.\n\nThis insignia belonged to an Alliance soldier. I will see if I can determine who, and I will speak with their family, should they have one.\n\nLet me know if you find more of these." }
quests[53118] = { id = 53118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dented Coin", progress = "What do you have to report?", completion = "Heh, what's this? Haven't seen a coin like this in a long time.\n\nUsed to use these around the time of the Second War. Supplies were limited, we needed a way to trade with the locals. They used these coins, and then so did we. \n\nStill smells like cannon powder, too. Ah, that takes me back.\n\nWell, what are you doing still standing there? Dismissed!" }
quests[53119] = { id = 53119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Sea Scroll", progress = "Yes? What do you have there?", completion = "Oh my, that scroll is old, even amongst the relics of the sea.\n\nThose that would commune with the waves have existed since long before our written history. Relics of the most ancient tide-speakers have all but disappeared from our world, lost to the deeps that spoke to them.\n\nI will put it in a safe place, thank you for bringing this to me." }
quests[53120] = { id = 53120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exotic Spices", progress = "Oh, hello! Did you have something for me?", completion = "Oh wow! I've never seen a mix of spices like that before.\n\nThe traders of the Great Sea make their own exotic spice mixes, each one is unique. I'll happily take them off of your hands if you find any more!\n\nThis one smells great! I can't wait to try it on... fish? No, carrots maybe? Hmm..." }
quests[53121] = { id = 53121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege of Boralus", objectives = "It really is a shame you missed it, {name}. Dwarven gryphon-riders got the jump on us, but I don't think they were counting on us packing so many trained killers onto one boat.\n\nEven Zelling got into the fun!\n\nI found this letter on one of the dwarven corpses. Looks like there's tensions between the Kul Tiran leadership and one of their houses, House Ashvane. This might give us a good opportunity to sow some chaos in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53122] = { id = 53122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron and speak to Darkcaller Yanka. She can tell you more about the Wickerman ceremony.", completion = "The Wickerman ceremony is a time honored tradition.  It is good to see the Horde joining us in celebration.", objectives = "Speak with Darkcaller Yanka in the Ruins of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53125] = { id = 53125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Into The Wicker", description = "Your followers have sent a report regarding the mission at Mudfisher Cove.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission at Fairwind Post?", completion = "It seems the mission to defend Mudfisher Cove was a success. Well done, {name}.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53126] = { id = 53126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wicker Totem", description = "The defense of Mudfisher Cove was successful. Well done, {name}.\n\nA mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar.\n\nTravel to Mudfisher Cove in Drustvar and see what power this totem contains.", completion = "This totem was recovered in the aftermath of the battle. It seems to resonate with some strange magic. Personally, I don't trust it...", objectives = "Speak with Garn Blackwolf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53127] = { id = 53127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", progress = "What's this?", completion = "There were rumors that Daelin searched for his daughter before his demise. If this letter is what I think it is, this is part of the reason we are at war.", objectives = "Take the Illegible Correspondence to someone in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53128] = { id = 53128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", progress = "What's this?", completion = "I can feel history in this scroll, {name}. If this letter contains what I think it does, it is a sad tale indeed.\n\nNow, let me see...", objectives = "Take the Illegible Correspondence to Kayla Mills in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53129] = { id = 53129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Orgrimmar can tell you what happened here.", progress = "Yes?", completion = "Ah, yes, I think I know why you have brought this to me, {name}. Sit, allow me to explain.", objectives = "Take the Bloodied Sentinel's Glaive to Isabella in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53130] = { id = 53130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Stormwind can tell you what happened here.", progress = "Can I help you?", completion = "Aye, I recognize that look. You have seen Teldrassil, or what is left of it. Have a seat, {name}.", objectives = "Take the Bloodied Sentinel's Glaive to Kayla Mills in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53131] = { id = 53131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kings' Rest", objectives = "The Horde aren't just here on a san'layn shuttling mission. There are lots of high-ranking Horde figures here. Something's going on.\n\nOne perk of dealing with important Horde targets is that they tend to be carrying important information. Look at this map I found on one of the bodies. See the big red circle around \"Kings' Rest\"? What is Kings' Rest? Why don't the Alliance know about this?\n\nWe'll have to look into it as soon as we get back on land.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53146] = { id = 53146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulderfist Beatdown", description = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain.\n\nYou know what must be done.", progress = "Boulderfist ogres still plague Arathi.", completion = "You have thinned the clan's numbers? Well done.", objectives = "Kill 20 Boulderfist clan ogres in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53148] = { id = 53148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulderfist Beatdown", description = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi.\n\nYou know what must be done.", completion = "You have thinned the clan's numbers? Well done.", objectives = "Kill 20 Boulderfist clan ogres in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53149] = { id = 53149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiping Out the Witherbark", description = "The Witherbark tribe has a long and bloody history in the highlands of Arathi.\n\nShow them how much bloodier it can get.", progress = "Witherbark drums still echo across the Highlands.", completion = "Have the trolls been defeated? Well done.", objectives = "Kill 20 Witherbark tribe trolls in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53150] = { id = 53150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiping Out the Witherbark", description = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed.\n\nDrive the forest trolls from the Highlands.", completion = "Have the trolls been defeated? Well done.", objectives = "Kill 20 Witherbark tribe trolls in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53151] = { id = 53151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Wolves For The Den", description = "Your followers have sent a report regarding the mission at Wolf's Den.\n\nIt details that the mission was a success and that a pack of direwolves now guard the outpost.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission at Wolf's Den in Tiragarde Sound was a success. Well done, {name}.", objectives = "Deliver the mission report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53152] = { id = 53152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves for the Den", description = "The mission at Wolf's Den in Tiragarde Sound was a success. Well done, {name}.\n\nA pack of direwolves now patrols the area surrounding the outpost.\n\nTravel to Wolf's Den and see that the training of the wolves is up to our standard.", completion = "Throm-Ka, {name}. Rexxar has tamed a fine pack of wolves. They will serve the outpost well!", objectives = "Speak with Mukkral Blackvein.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53153] = { id = 53153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to The Defilers", description = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands.\n\nThe farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.", progress = "The Defilers still hold Go'Shek Farm.", completion = "You've driven them off? Well done.", objectives = "Kill 20 Defilers at Go'Shek Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53154] = { id = 53154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The League Will Lose", description = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands.\n\nThe northern farmland will belong to the Horde. Go, and defeat the humans.", completion = "You've driven them off? Well done.", objectives = "Kill 20 League of Arathor at Dabyrie's Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53155] = { id = 53155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notched Coin", description = "<This old, worn coin has clearly changed hands many times. The edges are rusty from years in the salty air of the Great Sea, and it features an unusual design.\n\nYou saw a number of these coins scattered around the island, they appear to be quite commonly used.>", completion = "Hello, have you come to sample our new brews?\n\nA coin? Oh, yes, I have seen these before, the island tribes use them.\n\nSometimes they visit us and purchase supplies. They live a very different life than us, always traveling from place to place, never settling down.\n\nWhen one group packs up to move on to a new island, it is not uncommon for another tribe to take their place. On and on they go like this.\n\nWhile you are here, we have be fishing up these strange gems. Can you make use of them?", objectives = "Bring the Notched Coin to Mili Wanderbrew in Jade Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53159] = { id = 53159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coarse Leather", description = "It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come.\n\nLet's make sure our allies are well prepared.", progress = "Should you find any additional leather in your hunt, you know where to find me.", completion = "Quite an offering. Thank you.", objectives = "Donate 60 Coarse Leather to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53160] = { id = 53160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Crypt Key", description = "<A magical device found on the mogu island invaders, it contains no more power.\n\nYou are aware of similar devices that were used to activate ancient titan machinery in the mogu vaults of Pandaria.\n\nThis particular one teems with a foreboding presence.\n\nThe Lorewalkers may know more about this device.>", completion = "Oh, hello my friend. We do not get many visitors here any longer, it is good to see you. \n\nWhat is it you have there?\n\nAh, yes, I see. A rare device of mogu origin. We have seen these before, many years ago.\n\nDuring the Age of a Hundred Kings, the mogu found necromancy. Powerful mogu necro-lords ruled their tribes from crypts dug deep beneath the surface.\n\nMany such crypts remain, unearthed or awoken by the wound in the world, I cannot say which.\n\nOh! And I have something for you, as well. Here.", objectives = "Bring the key to Lorewalker Cho in Vale of Eternal Blossoms.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53161] = { id = 53161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of the Reefs", description = "<A light mist twists and curls around this ring as if caressing it.\n\nHolding this object makes you uneasy, deep within your soul. It feels as if invisible, icy hands from the lands of the dead are pulling at you.\n\nThere is no mistaking Helya's power.\n\nThe Valarjar will want to hear about this.>", completion = "Another ring? Hmph. Yes, we have been seeing them more frequently.\n\n<Valdemar grimaces.>\n\nHelya is growing in power.\n\nWhat, small one, are you surprised? Did you think she was defeated?\n\n<Valdemar laughs heartily.>\n\nYou cannot kill death!\n\nI thank you for making me laugh today, little friend.\n\nOdyn has heard about your search for Azerite, we have gathered what we could. \n\nHere, it is yours.", objectives = "Solve the riddle.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53162] = { id = 53162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Syndicate", description = "As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers.\n\nPunish them.", completion = "The Syndicate has been driven back to Alterac? Well done.", objectives = "Kill 20 Syndicate members at Dabyrie's Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53163] = { id = 53163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodwake Drinking Horn", description = "<A large drinking horn taken from one of the Bloodwake vrykul.\n\nThe sturdy craftsmanship has allowed it to survive many years of hard travel on the Great Sea.\n\nAs you hold the horn, you remember how fervently the vrykul you encountered were after the Azerite, but to what end?\n\nOther vrykul tribes may know more about the Bloodwake and their motivations.>", completion = "<Vydhar's leaves shake as you approach.>\n\nI sense a good story approaches, what do you seek? Answers, I know, about the Bloodwake.\n\nThere is a fleet, some say thousands of ships large, that floats on the Great Sea, led by the greatest raider to ever live. His name is Jorun, the Bloodwake.\n\nLong ago he left us to seek a life at sea. He lives only to raid, never in one place for long.\n\nPerhaps you, too will see him one day.\n\nThis old one thanks you for visiting. Take these minerals from my roots.", objectives = "Bring the horn to the wise Vydhar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53164] = { id = 53164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonic Stone", description = "<The stone vibrates to your touch. The frequency resonates throughout your body, and you feel refreshed.\n\nThe mantid likely use these stones to allow them to fly great distances across the sea.\n\nTo see them on the island was strange, the mantid took a heavy blow when Shek'zeer was destroyed, they should not be swarming now.\n\nThe denizens of Pandaria may have more information.>", completion = "Yes? We are quite busy here, as you can see, what is it?\n\nAh, I see you have also encountered the mantid swarm.\n\nOur fears are realized, the new empress has hatched. Princess Zara, no, now Grand Empress Shek'zara, is here.\n\nShe is as hotheaded and impulsive as mantid queens usually are, and has mobilized most of her forces to search for Azerite.\n\nWe know not why.\n\n<Qipan squishes a nearby bug between his fingers.>\n\nBut we do not like it.\n\nHere, Azerite taken from their corpses, take it.", objectives = "Show the stone to Sentinel Commander Qipan in Townlong Steppes.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53165] = { id = 53165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping Antiquities Theft" }
quests[53167] = { id = 53167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icetusk Fur Cloak", description = "<The fur on this cloak is worn and tattered, but it is still warm. It has seen many years in the harsh, unforgiving blizzards of the north.\n\nThe icetusk tribe has not been seen on Azeroth until now, someone in Northrend might know more about them.>", completion = "Hello friend, my you smell like strange fish, where have you been? Is that too personal of a question?  No matter, how can this one help you?\n\nAh yes, the Icetusk, a most curious tale of a small tribe.\n\nThey resisted the Lich King's promises and set out on huge canoes to find salvation.\n\nAnd yet, all they found was hardship and despair. In dark times, they turned to necromancy, and thus the tribe has lived on, but only barely. A sad tale.\n\nOh! I fished this up this morning, it is yours if you like.", objectives = "Show the fur to Tua'kea in Dragonblight.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53168] = { id = 53168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Spyglass", description = "<This spyglass allows you to see far off into the distance, but looking through it for too long gives you a headache.\n\nThe lens appears to have been specifically crafted for someone else's eyes.\n\nGiven the intricate detail on the spyglass, they'd likely provide a hefty reward for its return.>", completion = "Now what do you have there? Oh, oh oh OH, what is this!?\n\nMy spyglass!\n\nOh honey, I never thought I'd see you again. Do you know how expensive this thing was? I had to get the lens custom-made because of my right eye and all.\n\nYou didn't look through it, did you?\n\nListen, I don't tear up often, but I just might this time. It really means the world to me.\n\nHere, all the Azerite I got, its yours. It's... worth a lot... oof. That hurts. You take it though, really. Take it. Go ahead. It's fine.", objectives = "Return the spyglass.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53169] = { id = 53169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Core", description = "<A burned-out core from the elementals you encountered.\n\nWhen you concentrate, you can sense that some elemental energy still exists, deep within the core.\n\nThey were clearly after the Azerite, but why?\n\nIt might be time to call in an old favor.>", completion = "Yes? I am no longer in the business of fire prevention.\n\nOh, you have questions about the elemental planes? They are in quite a state at the moment. Though the elements are always tumultuous, things have gotten quite out of hand.\n\nThe presence of this Azerite has ignited the lesser lords, and each seeks to overthrow the current lords and take the plane for themselves.\n\nThey see this new element as a sign of elemental rebirth.\n\nI do not see this. Here, I do not want even the gems I have, take them.", objectives = "Bring the core to Duke Hydraxis in Azshara.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53170] = { id = 53170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unscarred Black Scale", description = "<An utterly pristine black dragon scale taken from the dragons you recently encountered.\n\nThe black dragonflight was completely decimated following Deathwing's demise and Wrathion's rise to power.\n\nYet the size indicates a younger dragon.\n\nThere is one person, one dragon, that you know will want to hear of this, but where IS Wrathion?\n\nYou surmise he may be some place familiar, fortified, and abandoned.>", completion = "Hello, I was told to expect you. Kindly hand over the scale.\n\nWe will, of course, compensate you.\n\nFirst in information. Have you heard of the Dragon Isles? Few have, and fewer have been there.\n\nWe have not found others of the master's kin... forthcoming in information.\n\nShould you uncover anything further in your travels, we will be awaiting a visit, with payment in kind.\n\nAnd second, in this Azerite you are seeking. Here, a hefty sum for your troubles.\n\nUntil we meet again.", objectives = "Attempt to find Wrathion in Blackrock Mountain.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53171] = { id = 53171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battered Twilight Scale", description = "<The worn scale of a twilight dragon, it has seen many years of fighting.\n\nThe twilight dragons were thought to have been defeated with the fall of Sinestra, how were there so many on the island?\n\nAnd who is leading the flight?>", completion = "Shh! Step back! We can't let them see us!\n\nWhat are you doing here? Who sent you?\n\n<Eryna listens as you explain the twilight attack.>\n\nYes, we know. It's those damn stone troggs, nothing stops their digging! They dug far deeper and further than we thought possible.\n\nWhat's more, when I really concentrate, I can feel the heartbeat of thousands of tiny creatures in there. We have no idea how many more eggs remain...\n\nSince you're out here, one of them had these gems on them, take them.", objectives = "Solve the riddle.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53172] = { id = 53172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Co. Business Plan", description = "<An enormous volume, and printed in very small print. You can't make it through even a few sentences before the words begin to swim before your eyes.\n\nThe Venture Company's long-term plan appears to be quite complex and nearly impossible to understand.\n\nOne thing is for certain: a competing enterprise would likely pay well to get their hands on this tome.>", completion = "Yeah? What do ya got there? Oh.\n\nListen, my name's on the back of that thing because I'm what you call an \"investor.\" I put money into a bet that the company's going to succeed or not.\n\nIt's all a little complicated, so don't worry your pretty little head. I didn't do anything wrong, technically! We're just leveraging some existing infrastructure to make a little gold.\n\nIt's harmless.\n\nHey, look, I've got a huge bag of Azerite right here! Why don't you take it with you? Too heavy for me, really.", objectives = "Confront Lizzarik in Ratchet.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53173] = { id = 53173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Syndicate", description = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers.\n\nPunish them.", completion = "The Syndicate has been driven back to Alterac? Well done.", objectives = "Kill 20 Syndicate members at Go'Shek Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53174] = { id = 53174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Eye", description = "<The murloc eye appears to have no magical properties of its own, but is still quite damp to the touch.\n\nYou have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose.\n\nThis is unsettling, even for the naga.>", completion = "Oh, hello, are you here about the terrible things happening to the murlocs?\n\nI've been hearing tales of terrifying magical experiments happening in the depths, entire murloc tribes being wiped out.\n\nThere is one area that they won't even go near anymore, the water bubbles ferociously and the heat is unbearable. The fish have all fled, everything has fled, what could be going on there?\n\nOh! They've been bringing me some of this Azerite, I'm not sure why. Do you want it?\n\nThanks for visiting!", objectives = "Solve the riddle.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53175] = { id = 53175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warfront Looms", description = "We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe.\n\nOne particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory.\n\nSpeak with Ralston Karn, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", completion = "You're {name}, with the 7th Legion?\n\nWelcome. We've heard about you. Let's get to work.", objectives = "Report to Ralston Karn in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53176] = { id = 53176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glittering Scarab", description = "<A magical trinket found on a tol'vir spellcaster, it appears to augment their casting abilities.\n\nIt seems to be very old, but is nearly pristine in form. \n\nThe tol'vir of Uldum may know more about the sudden appearance of the Amathet.>", completion = "<The scarab catches Kamses' eye.>\n\nI see you have met the Amathet.\n\nThe wound in the world has unearthed new tombs, and from one they emerged. \n\nThey speak little to us, believing us betrayers of our sacred duties. They believe that they, stewards of the titans, should control the Azerite.\n\nWorse, when they realized that Rajh and the others were slain, they constructed their own, new keepers.\n\nThey must have an active forge.\n\nI will give you what Azerite we have, be careful, they are dangerous.", objectives = "Bring the scarab to High Commander Kamses in Uldum.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53177] = { id = 53177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Compass", description = "<A compass found on a stranded pirate, it no longer functions. \n\nThe metal and craftsmanship indicate an origin in Stormwind.>", completion = "Hello, are you here to buy herbs?\n\nOh, what's that, a compass? It certainly looks familiar.\n\nThat idiot.\n\nHe was always seeking his fortune somewhere and never finding it. Completely useless here at home, too. Couldn't keep an herb alive to save his life.\n\nYou know what? I'm glad he's lost at sea. Leave him there.\n\nHere, I'll even give you his stash of Azerite, he would hate that.\n\nFinally free to pursue my own interests, now that's a breath of fresh air. I wonder if Kirsty's still available...", objectives = "Find the owner of the compass.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53178] = { id = 53178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorfin Hunting Spear", description = "<This spear is razor sharp, though it has clearly seen many years of hunting in the open sea.\n\nThe shaft has been broken in several places and repaired with what materials were available at the time. From the variety of repair materials, you surmise that the jinyu tribe you recently faced must travel extensively.\n\nThe friendly jinyu of Pandaria might know more about this strange tribe.>", completion = "Ah, yes, I do recognize this spear. You have encountered the Razorfin, then?\n\nThey are unique amongst Jinyu. Long ago the elder of the tribe was granted a vision of a great beast. So terrified was he that he named it \"Onoho,\" or \"Deep Shadow.\"\n\nHe dedicated his tribe to slaying the beast. They travel from island to island, never staying for long, in their endless quest. It is fascinating.\n\nI thank you for your visit. Some Azerite has washed ashore here, please take it, we have little use for it.", objectives = "Take the spear to Tired Shushen in Krasarang Wilds.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53179] = { id = 53179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executing Exorcisms", description = "Even in death, the Horde foolishly clings to Alliance territory.\n\nDrive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.", progress = "Vengeful ghosts remain in Ar'gorok.", completion = "You've cleared the ruins of ghosts? Well done.", objectives = "Kill 20 Vengeful Ghosts in Ar'gorok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53180] = { id = 53180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorus'arak's Carapace", description = "<The carapace from the nerubian lord Vorus'arak, it looks ancient.\n\nIt appears that Vorus'arak did not want to shed his shell, and instead wore the same scarred carapace for a very long time.\n\nAll across the carapace, strange markings have been carved. It seems to be a language of some kind.>", completion = "What is this? A carapace? Yes, I see, this writing is in my language. \n\nIt speaks of the swarm lord Vorus'arak, he has written of his journeys on his own chitin.\n\nHe tells of the War of the Spider, of his escape through the tunnels with his brood.\n\nVorus was a powerful digger, yet even his great strength flagged, and he was forced to consume much of his own young.\n\nIn the end, they found an island, and survived. Until you arrived.\n\nOur history is important to us, here are some gems for your time.", objectives = "Bring the carapace to Kilix the Unraveler in Dragonblight.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53181] = { id = 53181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druidic Fur", description = "<This fur teems with natural magic. The beasts you fought on the island were clearly not beasts at all, but druids.\n\nAt least they were before.\n\nWhat could have caused them to become feral?\n\nYou did not want to slay them, but they gave you no choice, didn't they?>", completion = "This fur... has not seem a change in form in quite some time. \n\nYou encountered my kin gone feral, I surmise? That... makes sense.\n\nFollowing the War of the Satyr, there were those among us that thought that the Pack was the only true way. That we were, at our core, wild creatures, and our humanoid forms are merely a guise.\n\nAs a flock they took wing and left us, never to be heard from again. Until now.\n\nI thank you for this information, here is some Azerite I have collected for the Speaker.", objectives = "Bring the fur to Loganaar in Moonglade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53182] = { id = 53182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strangling Root", description = "<The root twists and struggles in your grip, attempting to wrap itself around your arm.\n\nThe keepers you encountered must be powerfully attuned to nature to imbue their creations with such longetivity.\n\nRemembering the ferocity with which they fought against you makes you suddenly uneasy.\n\nWhy would these guardians of nature behave this way?\n\nSurely, someone must have the answers.>", completion = "This root tells me all that I need to know of your voyage: an island, teeming with the life spirit, and you met keepers there. \n\nI sense you are surprised at their actions.\n\nNot all of us that guard the natural world see your kind as allies. There are many of my kind that seek to preserve the balance above all things. Even if that means your death.\n\nI will not fault you for defending yourself, but I am powerless to subdue them as well.\n\nHowever, my fawns have gathered some Azerite for you.", objectives = "Take the root to Keeper Remulos in Moonglade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53183] = { id = 53183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wriggling Mass", description = "<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts.\n\nOne vision in particular surfaces in your mind again and again.\n\nIn your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle.\n\nAs you sink into the icy darkness, everything goes black.\n\nYou pocket the mass and shake the thoughts from your head.", completion = "Please, lower your weapon, I mean you no harm. The whispers ceased speaking to me on the day that the wound opened. \n\nI wish to spend my days atoning for what I have done in my life, perhaps I can help you.\n\nYou... I can see it in your eyes, you have seen the vision. \n\nThe goat, the pool, drowning in the icy blackness, does this sound familiar?\n\nI can tell you its meaning. It means we are fast closing in on the end of this world, friend.\n\nTake my Azerite, I have no need of it any longer.", objectives = "Locate someone who can explain the visions.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53184] = { id = 53184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weathered Pamphlet", description = "<This pamphlet appears to be a mass-produced flier advertising an Azerite-buying service.\n\nYou can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" \n\nThere is no mention of any of the dangers involved.\n\nThere is some information about who to contact at the bottom, however.>", completion = "Are you here about the pamphlet? \n\nWhat's wrong, expecting someone greener? Listen, we've all got to eat. I've got a family at home, and this war's taking all of the food away.\n\nNot my problem if some amateur adventurers with gold in their eyes get in a little trouble? That sounds more like your problem.\n\nNow if you're not going to sell me your Azerite, buzz off. Big G doesn't like it when I talk too much.\n\nUh, did I say G? Pretend I didn't.\n\nHere, just take some of my Azerite and keep quiet, ok?", objectives = "Find the pamphlet's originator.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53185] = { id = 53185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nAlliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!", completion = "The Alliance appreciates your generosity, {name}. You've pushed us that much closer to victory!", objectives = "Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53186] = { id = 53186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Ambush at Grimwatt's Crash", description = "Your followers have sent a report regarding the mission at Grimwatt''s Crash.\n\nIt details that the mission was a success and the attacking blood trolls were defeated.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission for Grimwatt's Crash?", completion = "It seems the mission at Grimwatt's Crash was a success. Well done, {name}.", objectives = "Deliver the mission report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53187] = { id = 53187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Guest", description = "The mission to defend Grimwatt's Crash was a success. Well done, {name}.\n\nIn addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training.\n\nMake your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.", completion = "Blood crawgs aren't as difficult to train as long as you might think. See for yourself and take \"Spud\" here for a ride!", objectives = "Speak with Noella Davenport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53188] = { id = 53188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen Freestyle" }
quests[53189] = { id = 53189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slippery Slopes" }
quests[53190] = { id = 53190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executing Exorcisms", description = "Even in death, the Alliance foolishly clings to Horde territory.\n\nDrive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", progress = "Vengeful ghosts remain in Stromgarde.", completion = "You've cleared the ruins of ghosts? Well done.", objectives = "Kill 20 Vengeful Ghosts in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53192] = { id = 53192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", completion = "The elementals have been banished? Well done.", objectives = "Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53193] = { id = 53193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", progress = "Hostile elementals still befoul the Highlands.", completion = "The elementals have been banished? Well done.", objectives = "Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53194] = { id = 53194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Front", description = "I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nYvera Dawnwing maintains a portal directly to Stromgarde. She can help you.", completion = "Terrible business, war is. Really.\n\nGlad you could make it, soldier. Let's make this quick.", objectives = "Speak with Yvera Dawnwing to teleport to Stromgarde, then report to Captain Roderick Brewston.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53195] = { id = 53195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Akunda's Bite", description = "Greetings!\n\nWith the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you!\n\nNow, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.", progress = "Have some herbs for me?", completion = "The scent of these herbs is unmistakable.\n\nI'll make sure they're put to good use.", objectives = "Gather 20 Siren's Pollen for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53196] = { id = 53196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swab This!" }
quests[53197] = { id = 53197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touring the Front", description = "The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Grayson Bell, the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.", progress = "Cheers!", completion = "Nobody's been slaughtered by the Horde, then? Excellent.\n\nGlad you could make it back safely too, {name}.", objectives = "Report to Foreman Tully, Lumbering Leo, and Grayson Bell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53198] = { id = 53198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Boralus", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.", completion = "You're all caught up? Excellent.\n\nHolding a firm line in Arathi is critical to the Alliance's continued occupation of Lordaeron. We appreciate your support, both now and in the inevitable upcoming battle.", objectives = "Speak with Yvera Dawnwing to return to Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53205] = { id = 53205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Monelite Ore", description = "Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort.\n\nHave ye any ore ta spare?", progress = "Ye look like the kind o' lad that ought ta be carryin' loads o' ore around with ye!\n\nGot any ta spare?", completion = "Ah hah! I knew you were the type!\n\nI could tell by the way yer breeches were saggin' a bit low.", objectives = "Gather 20 Monelite Ore to Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53207] = { id = 53207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warfront Looms", description = "Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe.\n\nWe are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde.\n\nSpeak with Throk, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", completion = "You're {name}, with the Honorbound?\n\nWelcome. We've heard about you. Let's get to work.", objectives = "Report to Throk in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53208] = { id = 53208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Front", description = "We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nDruza Netherfang maintains a portal directly to Ar'gorok. She can help you.", completion = "War. It would be horrible if it weren't for all the amazing profit opportunities.\n\nYou're {name}, right? Let's get started.", objectives = "Speak with Druza Netherfang to teleport to Ar'gorok, then report to Wistel Silversnitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53209] = { id = 53209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nShow some pride and give what you can. For the Horde!", completion = "Lok'tar ogar!", objectives = "Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53210] = { id = 53210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touring the Front", description = "The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Flightgineer Krazzle. He can give you a quick look at Stromgarde, so you can see what we're up against.", progress = "Hey hey.", completion = "You're back from your tour? And nobody's been slaughtered by the Alliance? Nice.\n\nGlad you could make it back safely too, {name}.", objectives = "Report to Foreman Drogg, Graul, and Flightgineer Krazzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53211] = { id = 53211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coastal Healing Potion", description = "I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.", progress = "I don't suppose you have any healing potions to spare.\n\nI'm trying to maintain a healthy supply for the battle to come.", completion = "Oh, no...\n\n<Chelsea catches a falling potion in the palm of her hand before it hits the ground.>\n\nThat was a close one!\n\nThese wouldn't be very helpful if I dropped them, now would they?\n\nThanks again, {name}.", objectives = "Gather 10 Coastal Healing Potions for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53212] = { id = 53212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Zuldazar", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.", completion = "Welcome back.\n\nWe need to hold that line in Arathi, {name}. We'll be calling on you to help us out when the time comes.", objectives = "Speak with Druza Netherfang to return to Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53213] = { id = 53213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coastal Mana Potion", description = "One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota.\n\nYou wouldn't happen to know where one can acquire additional mana potions, would you?", progress = "I'm looking to acquire a few potions to sustain our allies in a long-fought battle. Have anything of the kind?", completion = "This is just what I was looking for.", objectives = "Bring 10 Coastal Mana Potions to Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53216] = { id = 53216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Shimmerscale", description = "I'll keep it simple: we need more Shimmerscale!\n\nI apologize for being so forward with you, but there's little time to waste.\n\nIf you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?", progress = "Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left unprotected on the battlefield.", completion = "With your help, our stockpiles will be well supplied in no time!", objectives = "Donate 100 Shimmerscale to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53217] = { id = 53217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coarse Leather Barding", description = "It's not just our allies we need to protect in the upcoming battle, but our equine friends as well!\n\nCan you lend a hand and ensure our allies receive the best possible armor for the battle ahead?", progress = "It's not just our allies needing protection in the battle to come, but our beasts as well.", completion = "These ensure our riders and beasts are well prepared.", objectives = "Gather 5 Coarse Leather Barding for Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53218] = { id = 53218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Monel-Hardened Hoofplates", description = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well.\n\nIf ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", progress = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies who're needin' help, but our beasts of battle as well.\n\nIf ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", completion = "Quite generous of ye, {name}. I'll be sure they're put ta good use.", objectives = "Gather 2 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53219] = { id = 53219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Monel-Hardened Stirrups", description = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction.\n\nIf yer able ta bring me a few I'll be sure they're put ta good use.", progress = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction.\n\nIf yer able ta bring me a few I'll be sure they're put ta good use.", completion = "Excellent work, lad.\n\nI'll get these ta our riders right away.", objectives = "Gather 2 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53221] = { id = 53221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Missing Supplies", description = "Your followers have sent a report regarding the mission at Vulture's Nest.\n\nIt details that the mission was a success and the lost supply shipment has been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission for Vulture's Nest?", completion = "It seems the mission to recover the supplies was a success. Well done, {name}.", objectives = "Deliver the mission report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53222] = { id = 53222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Supplies", description = "The mission to recover the supplies was a success. Well done, {name}.\n\nThe supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for.\n\nMake your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug.", completion = "Good to see you, {name}! Without your help we would have lost the kegs I ordered! Help yourself to all you can drink, let the brew flow forth!", objectives = "Speak with Buzz Crankchug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53223] = { id = 53223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Grilled Catfish", description = "Greetings, traveler.\n\nI was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?", progress = "I was asked to ensure our food supplies are never left wanting, though lately our fish supplies have been running low.\n\nHave any fish you would care to donate?", completion = "This will do just fine. I'll be sure our allies are well fed before the battle begins.", objectives = "Gather 5 Grilled Catfish for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53224] = { id = 53224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Seasoned Loins", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", progress = "A hearty meat provides the nourishment our allies deserve.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", completion = "I'll get these to our supply officers right away.", objectives = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53225] = { id = 53225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Great Sea Catfish", description = "Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish.\n\nIf we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. \n\nIf you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", progress = "If we're going to keep our allies well fed and full of fish, we'll need to make sure our stockpile is ready.\n\nIf you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", completion = "Looks like the great fish feast continues.\n\nOur allies will be delighted.", objectives = "Gather 40 Great Sea Catfish for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53226] = { id = 53226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Tidespray Linen", progress = "There is no such thing as too much linen. It is better to maintain a strong supply than be left wanting.", completion = "How thoughtful of you.", objectives = "Gather 40 Tidespray Linen for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53227] = { id = 53227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Spirit of Freedom", progress = "I have a keen eye for quality when it comes to handcrafted items. I'm looking for one item in particular that may be of use to us on the field of battle.", completion = "Splendid work, {name}. Absolutely beautiful.", objectives = "Gather 2 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53228] = { id = 53228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Phalanx Defense", progress = "Threading and craftsmanship are not all that matter. Our work speaks to the heart of our dedication, providing a beacon of hope on the field of battle.\n\nI am looking for such an item, one that is crafted by a highly skilled tailor. Have you seen anything of the sort?", completion = "What beautiful craftsmanship. I could spend hours looking this over, though I must continue with our preparations.\n\nThank you for this.", objectives = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53229] = { id = 53229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Enchant Ring - Seal of Critical Strike", progress = "I was just about done filling orders for the next shipment then realized I was out of materials!\n\nDo you think you can help me fill the remaining orders?", completion = "Thanks for helping keep things on track. Where would we be without generous people like you?", objectives = "Gather 2 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53230] = { id = 53230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Enchant Ring - Seal of Versatility", progress = "I know it's short notice, but I'm trying to find a few more enchantments to add to our next shipment.", completion = "Nice work! Ya know, you're the reason we're able to prepare so quickly.\n\nThanks a bunch!", objectives = "Gather 2 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53231] = { id = 53231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Gloom Dust", progress = "I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help.\n\nWould you be willing to donate a few supplies?", completion = "Wow! I knew I could count on you.", objectives = "Gather 20 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53232] = { id = 53232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Incendiary Ammunition", description = "Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by.\n\nToday I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.", progress = "Though our ammunition supplies are faring well, it's my duty to maintain a stockpile of additional resources, especially those that are harder to come by.\n\nWould you let me know if you stumble upon munitions with incendiary properties?", completion = "I'll be sure to handle these with care.", objectives = "Gather 2 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53233] = { id = 53233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Frost-Laced Ammunition", description = "Hey there!\n\nTransmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected!\n\nFrom what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic!\n\nMaybe they'd even let me keep one to examine!", progress = "I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few of these I'm sure our munitions officers would be ecstatic!", completion = "Wow! These are magnificent! The craftsmanship alone is... \n\nApologies, I get carried away sometimes.\n\nTake care!", objectives = "Gather 2 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53234] = { id = 53234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: F.R.I.E.D.", description = "You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected!\n\nWe've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. \n\nIf you have any to spare I'll make sure they're put to good use.", progress = "We've started a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list.\n\nIf you have any to spare I'll make sure they're put to good use.", completion = "What a find!\n\nI'll make sure these are handled with care.", objectives = "Gather 3 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53235] = { id = 53235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Intellect", description = "Enlightenment guides our path to victory. In battle, we fight as one.\n\nShare your knowledge and skills with me. Generosity is never forgotten.", progress = "Enlightenment presents opportunity for victory.", completion = "Your gift is most appreciated.", objectives = "Gather 3 War-Scroll of Intellect for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53236] = { id = 53236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Fortitude", progress = "The opportunity for strength and fortitude present themselves when facing difficult situations.", completion = "May preparation guide us, and bravery shine within.", objectives = "Gather 3 War-Scroll of Fortitude for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53237] = { id = 53237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Battle Shout", progress = "With preparation comes success.", completion = "My thanks.", objectives = "Gather 3 War-Scroll of Battle Shout for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53238] = { id = 53238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Versatile Kyanite", progress = "Our gem supplies are running low. Any you can spare would be greatly appreciated.", completion = "Splendid.", objectives = "Gather 20 Versatile Kyanite for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53239] = { id = 53239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Straddling Viridium", progress = "We need more gems!", completion = "Wonderful specimens.\n\nThank you for your support.", objectives = "Gather 15 Straddling Viridium for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53240] = { id = 53240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Deadly Solstone", progress = "Have you seen any of these lately?", completion = "You're quite the gem, aren't you?", objectives = "Gather 20 Deadly Solstone for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53241] = { id = 53241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coastal Mana Potion", progress = "I know ya be tinkin' I be runnin' out of supplies again. And I ain't here ta argue about you bein' right.\n\nSo if ya can bring me some o' dem mana potions, I be gettin' back ta business and we be preparin' for de battle to come.", completion = "I be passin' dese along.\n\nThanks for ya donation." }
quests[53242] = { id = 53242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coastal Healing Potion", progress = "A few o' dem healin' potions be a nice addition ta our supply. Bring me a few and I be sure dey be gettin' where dey need ta be.", completion = "I be knowin' I can count on you." }
quests[53243] = { id = 53243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Coarse Leather Barding", progress = "Our riders are not the only ones requiring protection on the field of battle, but our beasts as well.\n\nIf you were to bring me a supply of barding I will personally see to it that our riders and their beasts are outfitted and ready for the battle to come.", completion = "Thank you, {name}. I will see to it that our allies get the protection they deserve." }
quests[53244] = { id = 53244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Shimmerscale", progress = "Armor is in short supply. We'll get nowhere fast unless we find an abundance of additional materials.", completion = "A delivery like this will keep us busy.\n\nThanks for your help." }
quests[53245] = { id = 53245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Monel-Hardened Hoofplates", progress = "A few more hoofplates and the next shipment will be ready.\n\nI'll be here if you find any in your travels.", completion = "Good work. I'll get them loaded into our shipment immediately." }
quests[53246] = { id = 53246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Monel-Hardened Stirrups", progress = "Our riders need new stirrups before they're sent off to battle.", completion = "Strong craftsmanship. Did you make these yourself?" }
quests[53247] = { id = 53247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Spirit of Freedom", progress = "Battle standards are in high demand.", completion = "Did you make this?\n\nThe embroidery is second to none." }
quests[53248] = { id = 53248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Battle Flag: Phalanx Defense", progress = "We must provide our allies the means to strengthen their defenses.", completion = "Quite the piece. I'll make sure it is put to good use." }
quests[53249] = { id = 53249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Tidespray Linen", progress = "It's better to be well prepared than in short supply. If you have any linen to spare, we'll make good use of it.", completion = "Very generous of you, {name}." }
quests[53250] = { id = 53250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Fortitude", progress = "Not everyone is born a courageous warrior, but who says you can't temporarily behave as such?", completion = "These will do quite nicely." }
quests[53251] = { id = 53251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Battle Shout", progress = "This particular scroll has quite a powerful effect. Perhaps you're able to acquire such an item?", completion = "Yes. This will do." }
quests[53252] = { id = 53252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: War-Scroll of Intellect", progress = "Years of study have allowed us to produce scrolls capable of enhancing one's intellect. Have you seen such an item recently? I would die to get my hands on one.", completion = "Fine work." }
quests[53253] = { id = 53253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Enchant Ring - Seal of Versatility", progress = "If ya got somethin' ta give ta be helpin' out da effort, I be here waitin'.", completion = "Ah, yes. Dis be exactly what I was lookin' for.", objectives = "Gather 2 Enchant Ring - Seal of Versatility for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53254] = { id = 53254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Enchant Ring - Seal of Critical Strike", progress = "Armor, blades, spears... we be ready. Only ting missin' is a few more enchantments.", completion = "Very nice.", objectives = "Gather 2 Enchant Ring - Seal of Critical Strike for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53255] = { id = 53255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Gloom Dust", progress = "Special enchantments contain de power ta give our allies a fightin' chance.\n\nYou be findin' any in ya journeys?", completion = "Ya read my mind.", objectives = "Gather 20 Enchant Weapon - Stalwart Navigation for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53256] = { id = 53256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Deadly Solstone", progress = "Got some gems for me?", completion = "These are a cut above the rest." }
quests[53257] = { id = 53257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Versatile Kyanite", progress = "Any interesting finds lately?", completion = "Thank you kindly." }
quests[53258] = { id = 53258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Straddling Viridium", progress = "I'd love to get my hands on a few gems. Have any to spare?", completion = "Yes. These will do just fine." }
quests[53259] = { id = 53259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: F.R.I.E.D.", progress = "We're well on our way with munitions. Only thing left we could really use is something with a bit more kick, if ya know what I mean.", completion = "Kaaaa-boooom! Hah!\n\nI can't wait to see these in action." }
quests[53260] = { id = 53260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Incendiary Ammunition", progress = "We've got a good amount of munitions in our stockpile, but we're always lookin' for something with a bit more kick.", completion = "I can't wait to see these in action!" }
quests[53261] = { id = 53261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Frost-Laced Ammunition", progress = "Ya know what'll really surprise our enemies? The unexpected.\n\nAnd I know just the thing.", completion = "They're never gonna see it comin'!" }
quests[53262] = { id = 53262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Seasoned Loins", progress = "Have any loins you would like to donate?", completion = "Very generous of you." }
quests[53263] = { id = 53263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Grilled Catfish", progress = "Fish provides great nourishment.", completion = "This is a wonderful treat." }
quests[53264] = { id = 53264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Great Sea Catfish", progress = "A belly full of fish is a wonderful feeling.", completion = "You are very kind, {name}. Thank you." }
quests[53265] = { id = 53265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Gold", description = "We've spent a great deal of time and resources preparing for the battle to come. \n\nAs we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. \n\nWould you like to make a donation?", progress = "As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice.\n\nWould you like to make a donation?", completion = "How generous of you, {name}.", objectives = "Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53266] = { id = 53266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flourishing Sea Stalks" }
quests[53267] = { id = 53267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Dino Research", description = "Your followers have sent a report regarding the mission at Verdant Hollow.\n\nIt details that the mission was a success and a variety of dinasaur specimens have been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission for Verdant Hollow?", completion = "It seems the mission was a success. Well done, {name}.", objectives = "Deliver the mission report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[53268] = { id = 53268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dino Research", description = "The mission to gather research specimens was a success. Well done, {name}.\n\nYou should check in with the outpost commander and inspect the specimens yourself.\n\nMake your way to Verdant Hollow in Zuldazar and speak with Argrim Stonedeep.", completion = "Och, yer team did their job alright! Look at these wee dinasaur hatchlings...there's more o' them than us!", objectives = "Speak with Argrim Stonedeep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
