quests[53276] = { id = 53276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts", description = "An engineer has been assigned to Mugamba Overlook to build a scrapping machine.\n\nThe mission to salvage materials for the machine was a success thanks to your leadership.\n\nMake your way to Mugamba Overlook in Zuldazar and meet with Gilblin Clockspark. He has been overseeing the upgrades for the outpost.", completion = "This machine here will break anything apart! Go ahead, try it out!", objectives = "Speak with Gilblin Clockspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
